export async function submit(queue, job) {
  queue.publish(job);
  return { accepted: true };
}

files.src/worker.js:
export async function claim(db, id) {
  const row = await db.get(id);
  if (row.status !== 'ready') return false;
  await db.update(id, { status: 'running' });
  return true;
}

files.src/format.js:
const VERSION = 2;
export function format(value) {
  if (VERSION === 1) return String(value);
  return JSON.stringify(value);
}

files.src/retry.js:
export async function retry(operation) {
  try { return await operation(); } catch (_) { return null; }
}

files.src/archive.js:
export function archive(record) {
  if (record.locked) return false;
  record.archived = true;
  return true;
}

